int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    char *S = (char *)malloc((N + 5) * sizeof(char));
    scanf("%s", S + 1);

    Seg *ops = (Seg *)malloc((M + 1) * sizeof(Seg));
    for (int i = 0; i < M; ++i) {
        scanf("%d %d", &ops[i].l, &ops[i].r);
    }

    /* Merge intervals.
       Because l_i is non-decreasing, sorting is not necessary, but harmless if input guarantees hold. */
    if (M == 0) {
        puts("1");
        free(S);
        free(ops);
        return 0;
    }

    int *L = (int *)malloc((M + 1) * sizeof(int));
    int *R = (int *)malloc((M + 1) * sizeof(int));
    int cnt = 0;

    int curL = ops[0].l, curR = ops[0].r;
    for (int i = 1; i < M; ++i) {
        if (ops[i].l <= curR) {
            if (ops[i].r > curR) curR = ops[i].r;
        } else {
            L[cnt] = curL;
            R[cnt] = curR;
            cnt++;
            curL = ops[i].l;
            curR = ops[i].r;
        }
    }
    L[cnt] = curL;
    R[cnt] = curR;
    cnt++;

    /* Prefix sum of ones */
    int *pref = (int *)malloc((N + 1) * sizeof(int));
    pref[0] = 0;
    for (int i = 1; i <= N; ++i) {
        pref[i] = pref[i - 1] + (S[i] == '1');
    }

    ll ans = 1;

    /* Each merged connected component [L,R] can realize any number of ones
       from max ones in mandatory-overlap positions to total ones in [L,R].
       For binary strings under arbitrary permutations on overlapping intervals,
       number of distinct outcomes for the component equals len + 1,
       where len = R-L+1 and only total count of ones matters across the component.
       More precisely, all distributions of total ones inside the merged component
       are reachable, so count = total_ones + zeros + 1? No:
       distinct strings over a connected fully swappable component depend only on
       total ones in the component and positions outside fixed? Actually the whole
       merged component becomes arbitrarily permutable, hence number of distinct
       strings on that component is C(len, ones), which is too large.

       But the allowed operations are permutations within each interval, not arbitrary
       sequence preserving outside. Overlapping intervals generate full symmetric group
       on the union, so indeed any arrangement with same number of ones in the union
       is reachable. Therefore distinct final global strings factor by components as
       product of C(len, ones_component).
    */

    /* Precompute factorials/inv factorials up to N */
    ll *fact = (ll *)malloc((N + 1) * sizeof(ll));
    ll *invfact = (ll *)malloc((N + 1) * sizeof(ll));
    fact[0] = 1;
    for (int i = 1; i <= N; ++i) fact[i] = fact[i - 1] * i % MOD;

    /* fast pow */
    ll base = fact[N], exp = MOD - 2, res = 1;
    while (exp) {
        if (exp & 1) res = res * base % MOD;
        base = base * base % MOD;
        exp >>= 1;
    }
    invfact[N] = res;
    for (int i = N; i >= 1; --i) invfact[i - 1] = invfact[i] * i % MOD;

    for (int i = 0; i < cnt; ++i) {
        int l = L[i], r = R[i];
        int len = r - l + 1;
        int ones = pref[r] - pref[l - 1];
        ll ways = fact[len];
        ways = ways * invfact[ones] % MOD;
        ways = ways * invfact[len - ones] % MOD;
        ans = ans * ways % MOD;
    }

    printf("%lld\n", ans);

    free(S);
    free(ops);
    free(L);
    free(R);
    free(pref);
    free(fact);
    free(invfact);
    return 0;
}

