/*
We have a binary string S of length N and M interval operations [l_i, r_i].
For each interval, we may arbitrarily permute characters inside it.
l_i is non-decreasing.

Key fact:
For a connected component of positions formed by overlap/adjacency of intervals,
the operations allow arbitrary permutation of all characters inside that component.
So the final string is determined only by how many '1's end up in each component.

Thus, for each component of positions:
- let len = component length
- let ones = number of '1' initially inside it
- number of distinct assignments on this component = C(len, ones)

Positions not covered by any interval form singleton components, each contributes 1.

Since intervals are given with non-decreasing l_i, we can merge them in one pass.

Answer = product over merged interval components of C(length, ones) mod MOD.

We precompute factorials and inverse factorials up to N.
*/

public class Main {
    static final long MOD = 1_000_000_007L;

    static long modPow(long a, long e) {
        long r = 1;
        while (e > 0) {
            if ((e & 1) == 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int M = fs.nextInt();
        String S = fs.next();

        int[] pref = new int[N + 1];
        for (int i = 1; i <= N; i++) {
            pref[i] = pref[i - 1] + (S.charAt(i - 1) == '1' ? 1 : 0);
        }

        long[] fact = new long[N + 1];
        long[] invFact = new long[N + 1];
        fact[0] = 1;
        for (int i = 1; i <= N; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[N] = modPow(fact[N], MOD - 2);
        for (int i = N; i >= 1; i--) invFact[i - 1] = invFact[i] * i % MOD;

        long ans = 1;

        int curL = -1, curR = -1;
        for (int i = 0; i < M; i++) {
            int l = fs.nextInt();
            int r = fs.nextInt();

            if (curL == -1) {
                curL = l;
                curR = r;
            } else if (l <= curR) { // overlapping intervals merge
                if (r > curR) curR = r;
            } else {
                int len = curR - curL + 1;
                int ones = pref[curR] - pref[curL - 1];
                ans = ans * fact[len] % MOD * invFact[ones] % MOD * invFact[len - ones] % MOD;

                curL = l;
                curR = r;
            }
        }

        if (curL != -1) {
            int len = curR - curL + 1;
            int ones = pref[curR] - pref[curL - 1];
            ans = ans * fact[len] % MOD * invFact[ones] % MOD * invFact[len - ones] % MOD;
        }

        System.out.println(ans % MOD);
    }
}
